namespace sv_1161c51f867f41fb890ae888dfd3f0c6.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync() => Task.FromResult(Doctors);

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
            return Task.FromResult(slots);

        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates server-side rules and returns field-level errors.
    /// Key = field name, Value = error message.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
            errors["Email"] = "Account has outstanding balance";

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
            errors["PreferredDoctor"] = "Selected doctor does not accept self-pay patients";

        if (timeSlot == "10:00 AM")
            errors["TimeSlot"] = "This slot is no longer available";

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_1161c51f867f41fb890ae888dfd3f0c6.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book an Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    @* ── STEP 1: Patient Information ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!ShowStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ── STEP 2: Appointment Details ── *@
    @if (ShowStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.PreferredDoctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in Doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.PreferredDoctor" />
                @if (serverErrors.ContainsKey("PreferredDoctor"))
                {
                    <div class="validation-message">@serverErrors["PreferredDoctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in AvailableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="GoBackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-outline-primary" @onclick="CheckAvailability">
                    Check Availability
                </button>
                <button type="submit" class="btn btn-primary" disabled="@(!AvailabilityChecked)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (BookingConfirmed)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private List<string> Doctors { get; set; } = [];
    private List<string> AvailableSlots { get; set; } = [];
    private bool ShowStep2 { get; set; }
    private bool AvailabilityChecked { get; set; }
    private bool BookingConfirmed { get; set; }
    private Dictionary<string, string> serverErrors = new();
    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        Doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var validationMessages = new ValidationMessageStore(editContext);

        bool valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Email) || !Model.Email.Contains('@'))
        {
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            valid = false;
        }

        // Rely on DataAnnotationsValidator; trigger validation by checking the edit context
        editContext = new EditContext(Model);
        if (editContext.Validate())
        {
            // Only proceed if step-1 fields are filled (step-2 fields are optional at this point)
            if (!string.IsNullOrWhiteSpace(Model.PatientName)
                && !string.IsNullOrWhiteSpace(Model.Email)
                && !string.IsNullOrWhiteSpace(Model.Phone)
                && !string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            {
                ShowStep2 = true;
            }
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        AvailabilityChecked = false;
        serverErrors.Clear();
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            AvailableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.PreferredDoctor,
                DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            AvailableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        AvailabilityChecked = false;

        if (string.IsNullOrWhiteSpace(Model.PreferredDoctor)
            || !Model.AppointmentDate.HasValue
            || string.IsNullOrWhiteSpace(Model.TimeSlot)
            || string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            // Let DataAnnotations handle missing-field errors
            return;
        }

        if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            serverErrors["AppointmentDate"] = "Date must be in the future";
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            AvailabilityChecked = true;
        }
    }

    private void GoBackToStep1()
    {
        ShowStep2 = false;
        AvailabilityChecked = false;
        serverErrors.Clear();
    }

    private void HandleSubmit()
    {
        if (AvailabilityChecked)
        {
            BookingConfirmed = true;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_1161c51f867f41fb890ae888dfd3f0c6.Components.Pages;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required")]
    [Phone(ErrorMessage = "Invalid phone number")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor")]
    public string PreferredDoctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

