@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext editContext = null!;
    private ValidationMessageStore validationMessages = null!;
    private List<string> DoctorList { get; set; } = [];
    private List<string> AvailableSlots { get; set; } = [];
    private bool ShowStep2 { get; set; }
    private bool AvailabilityChecked { get; set; }
    private bool BookingConfirmed { get; set; }

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        validationMessages = new ValidationMessageStore(editContext);
        DoctorList = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        validationMessages.Clear();

        var step1Results = new List<ValidationResult>();
        var step1Fields = new[] { nameof(Model.PatientName), nameof(Model.Email), nameof(Model.Phone), nameof(Model.InsuranceProvider) };
        bool valid = true;

        foreach (var field in step1Fields)
        {
            var value = typeof(AppointmentModel).GetProperty(field)!.GetValue(Model);
            var context = new ValidationContext(Model) { MemberName = field };
            var results = new List<ValidationResult>();
            if (!Validator.TryValidateProperty(value, context, results))
            {
                valid = false;
                var fieldId = editContext.Field(field);
                foreach (var result in results)
                {
                    validationMessages.Add(fieldId, result.ErrorMessage!);
                }
            }
        }

        editContext.NotifyValidationStateChanged();

        if (valid)
        {
            ShowStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        AvailabilityChecked = false;
        ClearServerErrors();
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            AvailableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.PreferredDoctor,
                DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            AvailableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        ClearServerErrors();
        AvailabilityChecked = false;

        // Validate step-2 fields via DataAnnotations
        var step2Fields = new[] { nameof(Model.PreferredDoctor), nameof(Model.AppointmentDate), nameof(Model.TimeSlot), nameof(Model.ReasonForVisit) };
        bool valid = true;

        foreach (var field in step2Fields)
        {
            var value = typeof(AppointmentModel).GetProperty(field)!.GetValue(Model);
            var context = new ValidationContext(Model) { MemberName = field };
            var results = new List<ValidationResult>();
            if (!Validator.TryValidateProperty(value, context, results))
            {
                valid = false;
                var fieldId = editContext.Field(field);
                foreach (var result in results)
                {
                    validationMessages.Add(fieldId, result.ErrorMessage!);
                }
            }
        }

        if (valid && Model.AppointmentDate.HasValue && Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            validationMessages.Add(editContext.Field(nameof(Model.AppointmentDate)), "Date must be in the future");
            valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (!valid) return;

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            foreach (var (field, message) in errors)
            {
                validationMessages.Add(editContext.Field(field), message);
            }
            editContext.NotifyValidationStateChanged();
        }
        else
        {
            AvailabilityChecked = true;
        }
    }

    private void ClearServerErrors()
    {
        validationMessages.Clear();
        editContext.NotifyValidationStateChanged();
    }

    private void GoBackToStep1()
    {
        ShowStep2 = false;
        AvailabilityChecked = false;
        ClearServerErrors();
    }

    private void HandleSubmit()
    {
        if (AvailabilityChecked)
        {
            BookingConfirmed = true;
        }
    }
}

